    let mut drawn = 0;
    for _ in 0..count {
        let card_id = {
            let player_state = state.get_player_mut(player);
            player_state.draw_top_card()
        };
        match card_id {
            Some(id) => {
                state.move_object(id, Zone::Hand);
                state.events.push(GameEvent::CardDrawn { player, object: id });
                drawn += 1;
            }
